pub fn prepare_generation_run(
    options: GenerateOptions,
) -> Result<PreparedGenerationRun, GenerateError> {
    if !SUPPORTED_PROFILES.contains(&options.profile.as_str()) {
        return Err(GenerateError::InvalidProfile(options.profile));
    }

    fs::create_dir_all(&options.out_dir).map_err(|source| GenerateError::CreateOutputDir {
        path: options.out_dir.clone(),
        source,
    })?;

    Ok(PreparedGenerationRun {
        manifest_path: options.out_dir.join("manifest.json"),
        profile: options.profile,
        out_dir: options.out_dir,
        seed: options.seed,
        include_stress: options.include_stress,
    })
}

pub fn write_generation_run(
    run: &PreparedGenerationRun,
) -> Result<GenerationSummary, GenerateError> {
    let standards_lock_path = Path::new("standards.lock.json");
    let cargo_lock_path = Path::new("Cargo.lock");
    let registry_path = Path::new("cases/registry.json");

    let standards_lock = read_json_metadata(standards_lock_path)?;
    let standards_lock_bytes = read_bytes_metadata(standards_lock_path)?;
    let cargo_lock = read_bytes_metadata(cargo_lock_path)?;
    let registry = read_json_metadata(registry_path)?;

    let generated =
        generator::write_supported_cases(run, &registry, &sha256_hex(&standards_lock_bytes))?;
    let files_written = generated.files.len();
    let generated_case_ids: Vec<String> = generated
        .files
        .iter()
        .map(|file| file.case_id.clone())
        .collect();
    let manifest = build_generation_manifest(
        run,
        &standards_lock,
        &standards_lock_bytes,
        &cargo_lock,
        &registry,
        generated.files,
        &generated_case_ids,
        &generated.unavailable_cases,
    )?;
    let mut contents = serde_json::to_string_pretty(&manifest).map_err(|source| {
        GenerateError::SerializeManifest {
            path: run.manifest_path.clone(),
            source,
        }
    })?;
    contents.push('\n');

    fs::write(&run.manifest_path, contents).map_err(|source| GenerateError::WriteManifest {
        path: run.manifest_path.clone(),
        source,
    })?;

    Ok(GenerationSummary {
        files_written,
        manifest_written: true,
    })
}

pub fn validate_generated_root(
    root_dir: impl AsRef<Path>,
) -> Result<ValidationSummary, ValidateError> {
    let root_dir = root_dir.as_ref();
    let manifest_path = root_dir.join("manifest.json");
    let manifest_contents =
        fs::read_to_string(&manifest_path).map_err(|source| ValidateError::ReadManifest {
            path: manifest_path.clone(),
            source,
        })?;
    let manifest: Value = serde_json::from_str(&manifest_contents).map_err(|source| {
        ValidateError::ParseManifest {
            path: manifest_path.clone(),
            source,
        }
    })?;
    let files =
        manifest
            .get("files")
            .and_then(Value::as_array)
            .ok_or(ValidateError::ManifestShape {
                path: manifest_path.clone(),
                message: "missing files array",
            })?;
    let source_objects = build_manifest_source_object_map(&manifest_path, files)?;

    let mut failures = Vec::new();
    validate_wsi_pyramid_manifest_group(&manifest_path, files)?;
    for file in files {
        validate_manifest_references(&manifest_path, file, &source_objects, &mut failures)?;
        validate_manifest_file(root_dir, &manifest_path, file, &mut failures)?;
    }
    geometry::validate_manifest_geometry(root_dir, files, &mut failures);
    metadata::validate_manifest_metadata_corpus(files, &mut failures);

    Ok(ValidationSummary {
        manifest_path,
        files_checked: files.len(),
        failures,
    })
}

fn build_manifest_source_object_map(
    manifest_path: &Path,
    files: &[Value],
) -> Result<HashMap<String, ManifestSourceObject>, ValidateError> {
    let mut source_objects = HashMap::new();
    for file in files {
        let path = manifest_str(manifest_path, file, "/path", "file path must be a string")?;
        let case_id = manifest_str(manifest_path, file, "/case_id", "case_id must be a string")?;
        let sha256 = manifest_str(manifest_path, file, "/sha256", "sha256 must be a string")?;
        let study_instance_uid = manifest_str(
            manifest_path,
            file,
            "/uids/study_instance_uid",
            "uids study_instance_uid must be a string",
        )?;
        let sop_class_uid = manifest_str(
            manifest_path,
            file,
            "/dicom/sop_class_uid",
            "dicom sop_class_uid must be a string",
        )?;
        let sop_instance_uid = manifest_str(
            manifest_path,
            file,
            "/uids/sop_instance_uid",
            "uids sop_instance_uid must be a string",
        )?;
        let series_instance_uid = file
            .pointer("/uids/series_instance_uid")
            .and_then(Value::as_str)
            .map(ToOwned::to_owned);
        let frames = file.pointer("/image/frames").and_then(Value::as_u64);

        source_objects.insert(
            path.to_string(),
            ManifestSourceObject {
                case_id: case_id.to_string(),
                sha256: sha256.to_string(),
                study_instance_uid: study_instance_uid.to_string(),
                sop_class_uid: sop_class_uid.to_string(),
                sop_instance_uid: sop_instance_uid.to_string(),
                series_instance_uid,
                frame_of_reference_uid: file
                    .pointer("/uids/frame_of_reference_uid")
                    .and_then(Value::as_str)
                    .map(ToOwned::to_owned),
                frames,
                rows: file.pointer("/image/rows").and_then(Value::as_u64),
                columns: file.pointer("/image/columns").and_then(Value::as_u64),
                photometric_interpretation: file
                    .pointer("/image/photometric_interpretation")
                    .and_then(Value::as_str)
                    .map(ToOwned::to_owned),
                samples_per_pixel: file
                    .pointer("/image/samples_per_pixel")
                    .and_then(Value::as_u64),
                planar_configuration: file
                    .pointer("/image/planar_configuration")
                    .and_then(Value::as_u64),
            },
        );
    }
    Ok(source_objects)
}

fn validate_manifest_references(
    manifest_path: &Path,
    file: &Value,
    source_objects: &HashMap<String, ManifestSourceObject>,
    failures: &mut Vec<String>,
) -> Result<(), ValidateError> {
    let relative_path = manifest_str(manifest_path, file, "/path", "file path must be a string")?;
    let references = match file.get("references") {
        Some(Value::Array(references)) => references,
        Some(_) => {
            return Err(ValidateError::ManifestShape {
                path: manifest_path.to_path_buf(),
                message: "file references must be an array",
            });
        }
        None => {
            return Err(ValidateError::ManifestShape {
                path: manifest_path.to_path_buf(),
                message: "file references are missing",
            });
        }
    };

    for reference in references {
        let source_path = manifest_str(
            manifest_path,
            reference,
            "/source_path",
            "reference source_path must be a string",
        )?;
        let source_case_id = manifest_str(
            manifest_path,
            reference,
            "/source_case_id",
            "reference source_case_id must be a string",
        )?;
        let Some(source) = source_objects.get(source_path) else {
            failures.push(format!(
                "{relative_path}: reference_source_path: {source_path} is not generated in this run"
            ));
            continue;
        };

        validate_equal(
            failures,
            relative_path,
            "reference_source_case_id",
            source_case_id,
            source.case_id.as_str(),
        );
        validate_equal(
            failures,
            relative_path,
            "reference_sop_class_uid",
            manifest_str(
                manifest_path,
                reference,
                "/sop_class_uid",
                "reference sop_class_uid must be a string",
            )?,
            source.sop_class_uid.as_str(),
        );
        validate_equal(
            failures,
            relative_path,
            "reference_sop_instance_uid",
            manifest_str(
                manifest_path,
                reference,
                "/sop_instance_uid",
                "reference sop_instance_uid must be a string",
            )?,
            source.sop_instance_uid.as_str(),
        );

        if let Some(expected_series) = reference
            .get("series_instance_uid")
            .filter(|value| !value.is_null())
        {
            let expected_series = expected_series
                .as_str()
                .ok_or(ValidateError::ManifestShape {
                    path: manifest_path.to_path_buf(),
                    message: "reference series_instance_uid must be a string or null",
                })?;
            match source.series_instance_uid.as_deref() {
                Some(actual_series) => validate_equal(
                    failures,
                    relative_path,
                    "reference_series_instance_uid",
                    expected_series,
                    actual_series,
                ),
                None => failures.push(format!(
                    "{relative_path}: reference_series_instance_uid: source has no Series Instance UID"
                )),
            }
        }

        if let Some(frame_numbers) = reference
            .get("frame_numbers")
            .filter(|value| !value.is_null())
        {
            let frame_numbers = frame_numbers
                .as_array()
                .ok_or(ValidateError::ManifestShape {
                    path: manifest_path.to_path_buf(),
                    message: "reference frame_numbers must be an array or null",
                })?;
            for frame_number in frame_numbers {
                let frame_number = frame_number.as_u64().ok_or(ValidateError::ManifestShape {
                    path: manifest_path.to_path_buf(),
                    message: "reference frame_numbers items must be integers",
                })?;
                if frame_number == 0 {
                    failures.push(format!(
                        "{relative_path}: reference_frame_number: frame numbers are 1-based"
                    ));
                }
                if let Some(frames) = source.frames {
                    if frame_number > frames {
                        failures.push(format!(
                            "{relative_path}: reference_frame_number: frame {frame_number} exceeds source frame count {frames}"
                        ));
                    }
                }
            }
        }
    }

    if file.get("case_id").and_then(Value::as_str) == Some("derived/registration/spatial_ct_pair") {
        validate_spatial_registration_manifest_closure(
            manifest_path,
            file,
            source_objects,
            failures,
        )?;
    } else if file.get("case_id").and_then(Value::as_str)
        == Some("derived/registration/deformable_ct_pair")
    {
        validate_deformable_spatial_registration_manifest_closure(
            manifest_path,
            file,
            source_objects,
            failures,
        )?;
    } else if file.get("case_id").and_then(Value::as_str)
        == Some("derived/presentation-state/color_softcopy")
    {
        validate_color_softcopy_presentation_state_manifest_closure(
            manifest_path,
            file,
            source_objects,
            failures,
        )?;
    } else if file.get("case_id").and_then(Value::as_str) == Some("non-image/rt/image_linked") {
        validate_rt_image_manifest_closure(manifest_path, file, source_objects, failures)?;
    }

    Ok(())
}

fn validate_rt_image_manifest_closure(
    manifest_path: &Path,
    file: &Value,
    source_objects: &HashMap<String, ManifestSourceObject>,
    failures: &mut Vec<String>,
) -> Result<(), ValidateError> {
    const CASE_ID: &str = "non-image/rt/image_linked";
    const PLAN_PATH: &str = "non-image/rt/plan_linked/instance.dcm";

    let expected =
        file.pointer("/expected_rt_image/plan_reference")
            .ok_or(ValidateError::ManifestShape {
                path: manifest_path.to_path_buf(),
                message: "linked RT Image must declare its expected Plan reference",
            })?;
    let source = source_objects
        .get(PLAN_PATH)
        .ok_or(ValidateError::ManifestShape {
            path: manifest_path.to_path_buf(),
            message: "linked RT Image Plan source is missing from the manifest",
        })?;
    let expected_str = |pointer, message| manifest_str(manifest_path, expected, pointer, message);

    for (name, actual, locked) in [
        (
            "source_case_id",
            expected_str("/source_case_id", "Plan source_case_id must be a string")?,
            source.case_id.as_str(),
        ),
        (
            "source_path",
            expected_str("/source_path", "Plan source_path must be a string")?,
            PLAN_PATH,
        ),
        (
            "source_sha256",
            expected_str("/source_sha256", "Plan source_sha256 must be a string")?,
            source.sha256.as_str(),
        ),
        (
            "study_instance_uid",
            expected_str(
                "/study_instance_uid",
                "Plan study_instance_uid must be a string",
            )?,
            source.study_instance_uid.as_str(),
        ),
        (
            "sop_class_uid",
            expected_str("/sop_class_uid", "Plan sop_class_uid must be a string")?,
            source.sop_class_uid.as_str(),
        ),
        (
            "sop_instance_uid",
            expected_str(
                "/sop_instance_uid",
                "Plan sop_instance_uid must be a string",
            )?,
            source.sop_instance_uid.as_str(),
        ),
    ] {
        validate_equal(
            failures,
            CASE_ID,
            &format!("rt_image_plan_{name}"),
            actual,
            locked,
        );
    }

    match source.series_instance_uid.as_deref() {
        Some(locked) => validate_equal(
            failures,
            CASE_ID,
            "rt_image_plan_series_instance_uid",
            expected_str(
                "/series_instance_uid",
                "Plan series_instance_uid must be a string",
            )?,
            locked,
        ),
        None => failures.push(format!(
            "{CASE_ID}: rt_image_plan_series_instance_uid: source has no Series Instance UID"
        )),
    }
    match source.frame_of_reference_uid.as_deref() {
        Some(locked) => validate_equal(
            failures,
            CASE_ID,
            "rt_image_plan_frame_of_reference_uid",
            expected_str(
                "/frame_of_reference_uid",
                "Plan frame_of_reference_uid must be a string",
            )?,
            locked,
        ),
        None => failures.push(format!(
            "{CASE_ID}: rt_image_plan_frame_of_reference_uid: source has no Frame of Reference UID"
        )),
    }

    Ok(())
}

fn validate_color_softcopy_presentation_state_manifest_closure(
    manifest_path: &Path,
    file: &Value,
    source_objects: &HashMap<String, ManifestSourceObject>,
    failures: &mut Vec<String>,
) -> Result<(), ValidateError> {
    const CASE_ID: &str = "derived/presentation-state/color_softcopy";
    const SOURCE_CASE_ID: &str = "classic/sc/rgb_planar0_explicit_le";
    const SOURCE_PATH: &str = "classic/sc/rgb_planar0_explicit_le/instance.dcm";
    const SOURCE_SOP_CLASS_UID: &str = "1.2.840.10008.5.1.4.1.1.7";
    const SOP_CLASS_UID: &str = "1.2.840.10008.5.1.4.1.1.11.2";
    const TRANSFER_SYNTAX_UID: &str = "1.2.840.10008.1.2.1";

    let relative_path = manifest_str(manifest_path, file, "/path", "file path must be a string")?;
    let expected = file
        .get("expected_color_softcopy_presentation_state")
        .ok_or(ValidateError::ManifestShape {
            path: manifest_path.to_path_buf(),
            message: "Color Softcopy Presentation State must declare expected_color_softcopy_presentation_state",
        })?;
    let source = expected.get("source").ok_or(ValidateError::ManifestShape {
        path: manifest_path.to_path_buf(),
        message: "Color Softcopy Presentation State source must be an object",
    })?;

    for (name, pointer, locked) in [
        ("case_id", "/case_id", CASE_ID),
        ("sop_class_uid", "/dicom/sop_class_uid", SOP_CLASS_UID),
        (
            "iod_name",
            "/dicom/iod_name",
            "Color Softcopy Presentation State",
        ),
        ("modality", "/dicom/modality", "PR"),
        (
            "transfer_syntax_uid",
            "/dicom/transfer_syntax_uid",
            TRANSFER_SYNTAX_UID,
        ),
    ] {
        validate_equal(
            failures,
            relative_path,
            &format!("color_softcopy_manifest_{name}"),
            manifest_str(
                manifest_path,
                file,
                pointer,
                "Color Softcopy Presentation State DICOM identity must be a string",
            )?,
            locked,
        );
    }

    let source_path = manifest_str(
        manifest_path,
        source,
        "/source_path",
        "Color Softcopy Presentation State source_path must be a string",
    )?;
    validate_equal(
        failures,
        relative_path,
        "color_softcopy_source_path_locked",
        source_path,
        SOURCE_PATH,
    );
    let Some(actual) = source_objects.get(source_path) else {
        failures.push(format!(
            "{relative_path}: color_softcopy_source_path: {source_path} is not generated in this run"
        ));
        return Ok(());
    };

    for (name, expected_value, actual_value, locked) in [
        (
            "source_case_id",
            manifest_str(
                manifest_path,
                source,
                "/source_case_id",
                "Color Softcopy Presentation State source_case_id must be a string",
            )?,
            actual.case_id.as_str(),
            SOURCE_CASE_ID,
        ),
        (
            "source_sha256",
            manifest_str(
                manifest_path,
                source,
                "/source_sha256",
                "Color Softcopy Presentation State source_sha256 must be a string",
            )?,
            actual.sha256.as_str(),
            actual.sha256.as_str(),
        ),
        (
            "study_instance_uid",
            manifest_str(
                manifest_path,
                source,
                "/study_instance_uid",
                "Color Softcopy Presentation State source Study UID must be a string",
            )?,
            actual.study_instance_uid.as_str(),
            actual.study_instance_uid.as_str(),
        ),
        (
            "series_instance_uid",
            manifest_str(
                manifest_path,
                source,
                "/series_instance_uid",
                "Color Softcopy Presentation State source Series UID must be a string",
            )?,
            actual.series_instance_uid.as_deref().unwrap_or(""),
            actual.series_instance_uid.as_deref().unwrap_or(""),
        ),
        (
            "sop_class_uid",
            manifest_str(
                manifest_path,
                source,
                "/sop_class_uid",
                "Color Softcopy Presentation State source SOP Class UID must be a string",
            )?,
            actual.sop_class_uid.as_str(),
            SOURCE_SOP_CLASS_UID,
        ),
        (
            "sop_instance_uid",
            manifest_str(
                manifest_path,
                source,
                "/sop_instance_uid",
                "Color Softcopy Presentation State source SOP Instance UID must be a string",
            )?,
            actual.sop_instance_uid.as_str(),
            actual.sop_instance_uid.as_str(),
        ),
    ] {
        validate_equal(
            failures,
            relative_path,
            &format!("color_softcopy_{name}"),
            expected_value,
            actual_value,
        );
        validate_equal(
            failures,
            relative_path,
            &format!("color_softcopy_{name}_locked"),
            actual_value,
            locked,
        );
    }

    for (name, pointer, actual_value, locked) in [
        ("rows", "/rows", actual.rows, 2),
        ("columns", "/columns", actual.columns, 2),
        (
            "samples_per_pixel",
            "/samples_per_pixel",
            actual.samples_per_pixel,
            3,
        ),
        (
            "planar_configuration",
            "/planar_configuration",
            actual.planar_configuration,
            0,
        ),
    ] {
        let expected_value = manifest_u64(
            manifest_path,
            source,
            pointer,
            "Color Softcopy Presentation State source image value must be an integer",
        )?;
        validate_equal_debug(
            failures,
            relative_path,
            &format!("color_softcopy_source_{name}"),
            actual_value,
            Some(expected_value),
        );
        validate_equal(
            failures,
            relative_path,
            &format!("color_softcopy_source_{name}_locked"),
            expected_value,
            locked,
        );
    }
    let expected_photometric = manifest_str(
        manifest_path,
        source,
        "/photometric_interpretation",
        "Color Softcopy Presentation State source photometric interpretation must be a string",
    )?;
    validate_equal_debug(
        failures,
        relative_path,
        "color_softcopy_source_photometric_interpretation",
        actual.photometric_interpretation.as_deref(),
        Some(expected_photometric),
    );
    validate_equal(
        failures,
        relative_path,
        "color_softcopy_source_photometric_interpretation_locked",
        expected_photometric,
        "RGB",
    );
    validate_equal_debug(
        failures,
        relative_path,
        "color_softcopy_source_frame_count",
        actual.frames,
        Some(1),
    );

    let complete_instance = manifest_bool(
        manifest_path,
        source,
        "/complete_instance",
        "Color Softcopy Presentation State complete_instance must be a boolean",
    )?;
    validate_equal(
        failures,
        relative_path,
        "color_softcopy_source_complete_instance",
        complete_instance,
        true,
    );
    let same_study = manifest_bool(
        manifest_path,
        expected,
        "/same_study",
        "Color Softcopy Presentation State same_study must be a boolean",
    )?;
    validate_equal(
        failures,
        relative_path,
        "color_softcopy_same_study_declared",
        same_study,
        true,
    );
    validate_equal(
        failures,
        relative_path,
        "color_softcopy_same_study",
        manifest_str(
            manifest_path,
            file,
            "/uids/study_instance_uid",
            "Color Softcopy Presentation State Study UID must be a string",
        )?,
        actual.study_instance_uid.as_str(),
    );
    let different_series = manifest_bool(
        manifest_path,
        expected,
        "/different_series",
        "Color Softcopy Presentation State different_series must be a boolean",
    )?;
    validate_equal(
        failures,
        relative_path,
        "color_softcopy_different_series_declared",
        different_series,
        true,
    );
    let presentation_series_uid = manifest_str(
        manifest_path,
        file,
        "/uids/series_instance_uid",
        "Color Softcopy Presentation State Series UID must be a string",
    )?;
    if actual.series_instance_uid.as_deref() == Some(presentation_series_uid) {
        failures.push(format!(
            "{relative_path}: color_softcopy_different_series: presentation and source Series Instance UIDs must differ"
        ));
    }

    for (name, pointer, locked) in [
        (
            "referenced_series_items",
            "/relationship/referenced_series_items",
            1,
        ),
        (
            "referenced_image_items",
            "/relationship/referenced_image_items",
            1,
        ),
    ] {
        validate_equal(
            failures,
            relative_path,
            &format!("color_softcopy_{name}"),
            manifest_u64(
                manifest_path,
                expected,
                pointer,
                "Color Softcopy Presentation State relationship count must be an integer",
            )?,
            locked,
        );
    }
    let referenced_frames = manifest_array(
        manifest_path,
        expected,
        "/relationship/referenced_frame_numbers",
        "Color Softcopy Presentation State referenced_frame_numbers must be an array",
    )?;
    if !referenced_frames.is_empty() {
        failures.push(format!(
            "{relative_path}: color_softcopy_referenced_frame_numbers: complete-instance reference must not name frames"
        ));
    }
    validate_equal(
        failures,
        relative_path,
        "color_softcopy_applies_to_complete_instance",
        manifest_bool(
            manifest_path,
            expected,
            "/relationship/applies_to_complete_instance",
            "Color Softcopy Presentation State applies_to_complete_instance must be a boolean",
        )?,
        true,
    );

    let references = manifest_array(
        manifest_path,
        file,
        "/references",
        "Color Softcopy Presentation State references must be an array",
    )?;
    if references.len() != 1 {
        failures.push(format!(
            "{relative_path}: color_softcopy_manifest_closure: expected exactly one ordinary source reference"
        ));
        return Ok(());
    }
    let reference = &references[0];
    validate_equal(
        failures,
        relative_path,
        "color_softcopy_reference_relationship",
        manifest_str(
            manifest_path,
            reference,
            "/relationship",
            "Color Softcopy Presentation State reference relationship must be a string",
        )?,
        "source_image",
    );
    for (name, actual_value, expected_value) in [
        (
            "source_case_id",
            reference.get("source_case_id"),
            source.get("source_case_id"),
        ),
        (
            "source_path",
            reference.get("source_path"),
            source.get("source_path"),
        ),
        (
            "series_instance_uid",
            reference.get("series_instance_uid"),
            source.get("series_instance_uid"),
        ),
        (
            "sop_class_uid",
            reference.get("sop_class_uid"),
            source.get("sop_class_uid"),
        ),
        (
            "sop_instance_uid",
            reference.get("sop_instance_uid"),
            source.get("sop_instance_uid"),
        ),
    ] {
        validate_equal_debug(
            failures,
            relative_path,
            &format!("color_softcopy_reference_{name}"),
            actual_value,
            expected_value,
        );
    }
    if reference
        .get("frame_numbers")
        .is_some_and(|value| !value.is_null())
    {
        failures.push(format!(
            "{relative_path}: color_softcopy_reference_frame_numbers: complete-instance reference must omit frame numbers"
        ));
    }

    Ok(())
}

fn validate_deformable_spatial_registration_manifest_closure(
    manifest_path: &Path,
    file: &Value,
    source_objects: &HashMap<String, ManifestSourceObject>,
    failures: &mut Vec<String>,
) -> Result<(), ValidateError> {
    let relative_path = manifest_str(manifest_path, file, "/path", "file path must be a string")?;
    let expected = file
        .get("expected_deformable_spatial_registration")
        .ok_or(ValidateError::ManifestShape {
            path: manifest_path.to_path_buf(),
            message: "Deformable Spatial Registration must declare expected_deformable_spatial_registration",
        })?;
    let source = expected.get("source").ok_or(ValidateError::ManifestShape {
        path: manifest_path.to_path_buf(),
        message: "Deformable Spatial Registration source must be an object",
    })?;
    let same_study = expected
        .pointer("/common_instance_reference/same_study")
        .ok_or(ValidateError::ManifestShape {
            path: manifest_path.to_path_buf(),
            message: "Deformable Spatial Registration same-Study reference must be an object",
        })?;
    let other_studies = manifest_array(
        manifest_path,
        expected,
        "/common_instance_reference/other_studies",
        "Deformable Spatial Registration other-Studies references must be an array",
    )?;
    if other_studies.len() != 1 {
        failures.push(format!(
            "{relative_path}: deformable_registration_manifest_closure: expected exactly one other-Study reference"
        ));
        return Ok(());
    }
    let other_study = &other_studies[0];

    let identities = [
        ("source", source),
        ("same_study", same_study),
        ("other_study", other_study),
    ];
    for (name, identity) in identities {
        let source_path = manifest_str(
            manifest_path,
            identity,
            "/source_path",
            "Deformable Spatial Registration source_path must be a string",
        )?;
        let Some(actual) = source_objects.get(source_path) else {
            failures.push(format!(
                "{relative_path}: deformable_registration_{name}_source_path: {source_path} is not generated in this run"
            ));
            continue;
        };
        for (field, expected_value, actual_value) in [
            (
                "source_case_id",
                manifest_str(
                    manifest_path,
                    identity,
                    "/source_case_id",
                    "Deformable Spatial Registration source_case_id must be a string",
                )?,
                actual.case_id.as_str(),
            ),
            (
                "source_sha256",
                manifest_str(
                    manifest_path,
                    identity,
                    "/source_sha256",
                    "Deformable Spatial Registration source_sha256 must be a string",
                )?,
                actual.sha256.as_str(),
            ),
            (
                "study_instance_uid",
                manifest_str(
                    manifest_path,
                    identity,
                    "/study_instance_uid",
                    "Deformable Spatial Registration source Study UID must be a string",
                )?,
                actual.study_instance_uid.as_str(),
            ),
            (
                "sop_class_uid",
                manifest_str(
                    manifest_path,
                    identity,
                    "/sop_class_uid",
                    "Deformable Spatial Registration source SOP Class UID must be a string",
                )?,
                actual.sop_class_uid.as_str(),
            ),
            (
                "sop_instance_uid",
                manifest_str(
                    manifest_path,
                    identity,
                    "/sop_instance_uid",
                    "Deformable Spatial Registration source SOP Instance UID must be a string",
                )?,
                actual.sop_instance_uid.as_str(),
            ),
        ] {
            validate_equal(
                failures,
                relative_path,
                &format!("deformable_registration_{name}_{field}"),
                expected_value,
                actual_value,
            );
        }
        validate_equal(
            failures,
            relative_path,
            &format!("deformable_registration_{name}_series_instance_uid"),
            manifest_str(
                manifest_path,
                identity,
                "/series_instance_uid",
                "Deformable Spatial Registration source Series UID must be a string",
            )?,
            actual.series_instance_uid.as_deref().unwrap_or(""),
        );
        validate_equal(
            failures,
            relative_path,
            &format!("deformable_registration_{name}_frame_of_reference_uid"),
            manifest_str(
                manifest_path,
                identity,
                "/frame_of_reference_uid",
                "Deformable Spatial Registration source Frame of Reference UID must be a string",
            )?,
            actual.frame_of_reference_uid.as_deref().unwrap_or(""),
        );
    }

    for field in [
        "source_case_id",
        "source_path",
        "source_sha256",
        "study_instance_uid",
        "series_instance_uid",
        "sop_class_uid",
        "sop_instance_uid",
        "frame_of_reference_uid",
    ] {
        validate_equal_debug(
            failures,
            relative_path,
            &format!("deformable_registration_other_study_{field}"),
            other_study.get(field),
            source.get(field),
        );
    }

    let references = manifest_array(
        manifest_path,
        file,
        "/references",
        "Deformable Spatial Registration references must be an array",
    )?;
    if references.len() != 2 {
        failures.push(format!(
            "{relative_path}: deformable_registration_manifest_closure: expected exactly two ordinary references"
        ));
    }
    for (name, identity) in [("target", same_study), ("source", source)] {
        let source_path = identity.get("source_path");
        let reference = references
            .iter()
            .find(|reference| reference.get("source_path") == source_path);
        let Some(reference) = reference else {
            failures.push(format!(
                "{relative_path}: deformable_registration_{name}_ordinary_reference: no ordinary reference matches the manifest identity"
            ));
            continue;
        };
        for field in [
            "source_case_id",
            "source_path",
            "series_instance_uid",
            "sop_class_uid",
            "sop_instance_uid",
        ] {
            validate_equal_debug(
                failures,
                relative_path,
                &format!("deformable_registration_{name}_reference_{field}"),
                identity.get(field),
                reference.get(field),
            );
        }
    }
    Ok(())
}

fn validate_spatial_registration_manifest_closure(
    manifest_path: &Path,
    file: &Value,
    source_objects: &HashMap<String, ManifestSourceObject>,
    failures: &mut Vec<String>,
) -> Result<(), ValidateError> {
    let relative_path = manifest_str(manifest_path, file, "/path", "file path must be a string")?;
    let items = manifest_array(
        manifest_path,
        file,
        "/expected_spatial_registration/registration_items",
        "Spatial Registration registration_items must be an array",
    )?;
    if items.len() != 2 {
        failures.push(format!(
            "{relative_path}: spatial_registration_manifest_closure: expected exactly two registration items"
        ));
        return Ok(());
    }
    let references = manifest_array(
        manifest_path,
        file,
        "/references",
        "Spatial Registration references must be an array",
    )?;
    if references.len() != 2 {
        failures.push(format!(
            "{relative_path}: spatial_registration_manifest_closure: expected exactly two ordinary references"
        ));
    }
    for (index, item) in items.iter().enumerate() {
        let source = item.get("source").ok_or(ValidateError::ManifestShape {
            path: manifest_path.to_path_buf(),
            message: "Spatial Registration item source must be an object",
        })?;
        let source_path = manifest_str(
            manifest_path,
            source,
            "/source_path",
            "Spatial Registration source_path must be a string",
        )?;
        let Some(actual) = source_objects.get(source_path) else {
            failures.push(format!(
                "{relative_path}: spatial_registration_manifest_closure: {source_path} is not generated in this run"
            ));
            continue;
        };
        for (name, expected, actual) in [
            (
                "source_case_id",
                manifest_str(
                    manifest_path,
                    source,
                    "/source_case_id",
                    "Spatial Registration source_case_id must be a string",
                )?,
                actual.case_id.as_str(),
            ),
            (
                "source_sha256",
                manifest_str(
                    manifest_path,
                    source,
                    "/source_sha256",
                    "Spatial Registration source_sha256 must be a string",
                )?,
                actual.sha256.as_str(),
            ),
            (
                "study_instance_uid",
                manifest_str(
                    manifest_path,
                    source,
                    "/study_instance_uid",
                    "Spatial Registration source Study UID must be a string",
                )?,
                actual.study_instance_uid.as_str(),
            ),
            (
                "sop_class_uid",
                manifest_str(
                    manifest_path,
                    source,
                    "/sop_class_uid",
                    "Spatial Registration source SOP Class UID must be a string",
                )?,
                actual.sop_class_uid.as_str(),
            ),
            (
                "sop_instance_uid",
                manifest_str(
                    manifest_path,
                    source,
                    "/sop_instance_uid",
                    "Spatial Registration source SOP Instance UID must be a string",
                )?,
                actual.sop_instance_uid.as_str(),
            ),
        ] {
            validate_equal(
                failures,
                relative_path,
                &format!("spatial_registration_{index}_{name}"),
                expected,
                actual,
            );
        }
        let expected_series = manifest_str(
            manifest_path,
            source,
            "/series_instance_uid",
            "Spatial Registration source Series UID must be a string",
        )?;
        validate_equal(
            failures,
            relative_path,
            &format!("spatial_registration_{index}_series_instance_uid"),
            expected_series,
            actual.series_instance_uid.as_deref().unwrap_or(""),
        );
        let expected_frame = manifest_str(
            manifest_path,
            source,
            "/frame_of_reference_uid",
            "Spatial Registration source Frame of Reference UID must be a string",
        )?;
        validate_equal(
            failures,
            relative_path,
            &format!("spatial_registration_{index}_frame_of_reference_uid"),
            expected_frame,
            actual.frame_of_reference_uid.as_deref().unwrap_or(""),
        );
        if let Some(reference) = references.get(index) {
            for field in [
                "source_case_id",
                "source_path",
                "series_instance_uid",
                "sop_class_uid",
                "sop_instance_uid",
            ] {
                validate_equal_debug(
                    failures,
                    relative_path,
                    &format!("spatial_registration_{index}_reference_{field}"),
                    source.get(field),
                    reference.get(field),
                );
            }
        }
    }
    Ok(())
}

fn validate_manifest_file(
    root_dir: &Path,
    manifest_path: &Path,
    file: &Value,
    failures: &mut Vec<String>,
) -> Result<(), ValidateError> {
    let relative_path = manifest_str(manifest_path, file, "/path", "file path must be a string")?;
    validate_vl_single_frame_manifest_contract(manifest_path, file)?;
    validate_wsi_tiled_full_manifest_contract(manifest_path, file)?;
    validate_wsi_tiled_sparse_manifest_contract(manifest_path, file)?;
    validate_wsi_multiple_optical_paths_manifest_contract(manifest_path, file)?;
    validate_wsi_pyramid_manifest_member(manifest_path, file)?;
    let path = root_dir.join(relative_path);
    let bytes = match fs::read(&path) {
        Ok(bytes) => bytes,
        Err(err) => {
            failures.push(format!("{relative_path}: read_file: {err}"));
            return Ok(());
        }
    };

    validate_equal(
        failures,
        relative_path,
        "size_bytes",
        bytes.len() as u64,
        manifest_u64(
            manifest_path,
            file,
            "/size_bytes",
            "size_bytes must be an integer",
        )?,
    );
    validate_equal(
        failures,
        relative_path,
        "sha256",
        sha256_hex(&bytes),
        manifest_str(manifest_path, file, "/sha256", "sha256 must be a string")?,
    );

    let expected_sop_class = manifest_str(
        manifest_path,
        file,
        "/dicom/sop_class_uid",
        "dicom sop_class_uid must be a string",
    )?;
    let expected_sop_instance = manifest_str(
        manifest_path,
        file,
        "/uids/sop_instance_uid",
        "uids sop_instance_uid must be a string",
    )?;
    let expected_transfer_syntax = manifest_str(
        manifest_path,
        file,
        "/dicom/transfer_syntax_uid",
        "dicom transfer_syntax_uid must be a string",
    )?;
    let expected_implementation_class_uid = manifest_str(
        manifest_path,
        file,
        "/uids/implementation_class_uid",
        "uids implementation_class_uid must be a string",
    )?;
    let expected_implementation_version_name = file
        .pointer("/uids/implementation_version_name")
        .and_then(Value::as_str)
        .unwrap_or(IMPLEMENTATION_VERSION_NAME);

    validate_raw_part10_file(
        failures,
        relative_path,
        &bytes,
        expected_sop_class,
        expected_sop_instance,
        expected_transfer_syntax,
        expected_implementation_class_uid,
        expected_implementation_version_name,
    );

    let obj = match open_file(&path) {
        Ok(obj) => obj,
        Err(err) => {
            failures.push(format!("{relative_path}: open_file: {err}"));
            return Ok(());
        }
    };

    validate_equal(
        failures,
        relative_path,
        "file_meta_transfer_syntax",
        trim_uid(obj.meta().transfer_syntax()),
        expected_transfer_syntax,
    );
    validate_equal(
        failures,
        relative_path,
        "media_storage_sop_class_uid",
        trim_uid(obj.meta().media_storage_sop_class_uid()),
        expected_sop_class,
    );
    validate_equal(
        failures,
        relative_path,
        "media_storage_sop_instance_uid",
        trim_uid(obj.meta().media_storage_sop_instance_uid()),
        expected_sop_instance,
    );
    validate_equal(
        failures,
        relative_path,
        "implementation_class_uid",
        trim_uid(obj.meta().implementation_class_uid()),
        expected_implementation_class_uid,
    );
    validate_str_element(
        failures,
        relative_path,
        &obj,
        tags::SOP_CLASS_UID,
        "dataset_sop_class_uid",
        expected_sop_class,
    );
    validate_str_element(
        failures,
        relative_path,
        &obj,
        tags::SOP_INSTANCE_UID,
        "dataset_sop_instance_uid",
        expected_sop_instance,
    );
    validate_standard_baseline_elements(failures, relative_path, manifest_path, file, &obj)?;
    validate_family_standard_elements(failures, relative_path, &path, manifest_path, file, &obj)?;
    metadata::validate_manifest_metadata(
        relative_path,
        &bytes,
        expected_transfer_syntax,
        file,
        &obj,
        failures,
    );

    if file
        .pointer("/pixel_data/native_or_encapsulated")
        .and_then(Value::as_str)
        != Some("native")
    {
        validate_nonsquare_spacing_non_native_scope(failures, relative_path, manifest_path, file)?;
    }

    validate_str_element(
        failures,
        relative_path,
        &obj,
        tags::SYNTHETIC_DATA,
        "synthetic_data",
        manifest_str(
            manifest_path,
            file,
            "/expected_semantics/synthetic_data",
            "expected synthetic_data must be a string",
        )?,
    );

    match (file.get("image"), file.get("pixel_data")) {
        (Some(Value::Object(_)), Some(Value::Object(_))) => {
            validate_manifest_image_pixel_data(failures, relative_path, manifest_path, file, &obj)
        }
        (None | Some(Value::Null), None | Some(Value::Null)) => Ok(()),
        _ => {
            failures.push(format!(
                "{relative_path}: image_pixel_metadata_pair: image and pixel_data must both be present for image objects or both absent/null for non-image objects"
            ));
            Ok(())
        }
    }
}

fn validate_vl_single_frame_manifest_contract(
    manifest_path: &Path,
    file: &Value,
) -> Result<(), ValidateError> {
    let case_id = file.get("case_id").and_then(Value::as_str);
    let locked = match case_id {
        Some("vl/endoscopic/rgb_explicit_le") => Some((
            "vl_endoscopic_single_frame",
            "1.2.840.10008.5.1.4.1.1.77.1.1",
            "VL Endoscopic Image Storage",
            "VL Endoscopic Image",
            "ES",
            "LUNG",
        )),
        Some("vl/microscopic/rgb_explicit_le") => Some((
            "vl_microscopic_single_frame",
            "1.2.840.10008.5.1.4.1.1.77.1.2",
            "VL Microscopic Image Storage",
            "VL Microscopic Image",
            "GM",
            "EYE",
        )),
        _ => None,
    };
    let Some((iod_kind, sop_uid, sop_name, iod_name, modality, body_part)) = locked else {
        return if file.get("expected_vl_single_frame").is_some() {
            Err(ValidateError::ManifestShape {
                path: manifest_path.to_path_buf(),
                message: "expected_vl_single_frame is only valid for the two locked Phase 4 single-frame VL cases",
            })
        } else {
            Ok(())
        };
    };
    let expected = file
        .get("expected_vl_single_frame")
        .ok_or(ValidateError::ManifestShape {
            path: manifest_path.to_path_buf(),
            message: "Phase 4 single-frame VL case must define expected_vl_single_frame",
        })?;
    let locked_expected = serde_json::json!({
        "iod_kind": iod_kind,
        "sop_class_uid": sop_uid,
        "sop_class_name": sop_name,
        "iod_name": iod_name,
        "modality": modality,
        "transfer_syntax_uid": "1.2.840.10008.1.2.1",
        "body_part_examined": body_part,
        "laterality": "R",
        "image_type": ["ORIGINAL", "PRIMARY"],
        "acquisition_context_items": 0,
        "image": {
            "rows": 2, "columns": 2, "samples_per_pixel": 3,
            "photometric_interpretation": "RGB", "planar_configuration": 0,
            "bits_allocated": 8, "bits_stored": 8, "high_bit": 7, "pixel_representation": 0
        },
        "absent_content": ["number_of_frames", "frame_of_reference_uid", "specimen_module", "optical_path_module", "icc_profile_module"]
    });
    if expected != &locked_expected {
        return Err(ValidateError::ManifestShape {
            path: manifest_path.to_path_buf(),
            message: "expected_vl_single_frame must equal the exact locked case contract",
        });
    }
    for (pointer, locked_value) in [
        ("/dicom/sop_class_uid", Value::from(sop_uid)),
        ("/dicom/sop_class_name", Value::from(sop_name)),
        ("/dicom/iod_name", Value::from(iod_name)),
        ("/dicom/modality", Value::from(modality)),
        (
            "/dicom/transfer_syntax_uid",
            Value::from("1.2.840.10008.1.2.1"),
        ),
        ("/image/rows", Value::from(2)),
        ("/image/columns", Value::from(2)),
        ("/image/frames", Value::from(1)),
        ("/image/samples_per_pixel", Value::from(3)),
        ("/image/photometric_interpretation", Value::from("RGB")),
        ("/image/planar_configuration", Value::from(0)),
        ("/image/bits_allocated", Value::from(8)),
        ("/image/bits_stored", Value::from(8)),
        ("/image/high_bit", Value::from(7)),
        ("/image/pixel_representation", Value::from(0)),
        ("/pixel_data/vr", Value::from("OB")),
        ("/pixel_data/native_or_encapsulated", Value::from("native")),
        ("/pixel_data/frame_count", Value::from(1)),
    ] {
        if file.pointer(pointer) != Some(&locked_value) {
            return Err(ValidateError::ManifestShape {
                path: manifest_path.to_path_buf(),
                message: "single-frame VL manifest identity and pixel metadata must match expected_vl_single_frame",
            });
        }
    }
    if file.pointer("/uids/frame_of_reference_uid") != Some(&Value::Null) {
        return Err(ValidateError::ManifestShape {
            path: manifest_path.to_path_buf(),
            message: "single-frame VL manifest must declare frame_of_reference_uid null",
        });
    }
    Ok(())
}

fn validate_wsi_tiled_full_manifest_contract(
    manifest_path: &Path,
    file: &Value,
) -> Result<(), ValidateError> {
    const CASE_ID: &str = "vl/wsi/tiled_full_small";
    if file.get("case_id").and_then(Value::as_str) != Some(CASE_ID) {
        return if file.get("expected_wsi_tiled_full").is_some() {
            Err(ValidateError::ManifestShape {
                path: manifest_path.to_path_buf(),
                message: "expected_wsi_tiled_full is only valid for vl/wsi/tiled_full_small",
            })
        } else {
            Ok(())
        };
    }
    let expected = file
        .get("expected_wsi_tiled_full")
        .ok_or(ValidateError::ManifestShape {
            path: manifest_path.to_path_buf(),
            message: "vl/wsi/tiled_full_small must define expected_wsi_tiled_full",
        })?;
    let frame_of_reference_uid = expected
        .get("frame_of_reference_uid")
        .and_then(Value::as_str)
        .filter(|uid| is_manifest_uid(uid))
        .ok_or(ValidateError::ManifestShape {
            path: manifest_path.to_path_buf(),
            message: "expected_wsi_tiled_full frame_of_reference_uid must be a valid UID",
        })?;
    let specimen_uid = expected
        .pointer("/specimen/specimen_uid")
        .and_then(Value::as_str)
        .filter(|uid| is_manifest_uid(uid))
        .ok_or(ValidateError::ManifestShape {
            path: manifest_path.to_path_buf(),
            message: "expected_wsi_tiled_full specimen_uid must be a valid UID",
        })?;
    let locked = wsi_tiled_full_locked_contract(frame_of_reference_uid, specimen_uid);
    if expected != &locked {
        return Err(ValidateError::ManifestShape {
            path: manifest_path.to_path_buf(),
            message: "expected_wsi_tiled_full must equal the exact locked case contract",
        });
    }
    for (pointer, locked_value) in [
        (
            "/dicom/sop_class_uid",
            Value::from("1.2.840.10008.5.1.4.1.1.77.1.6"),
        ),
        (
            "/dicom/sop_class_name",
            Value::from("VL Whole Slide Microscopy Image Storage"),
        ),
        (
            "/dicom/iod_name",
            Value::from("VL Whole Slide Microscopy Image"),
        ),
        ("/dicom/modality", Value::from("SM")),
        (
            "/dicom/transfer_syntax_uid",
            Value::from("1.2.840.10008.1.2.1"),
        ),
        (
            "/uids/frame_of_reference_uid",
            Value::from(frame_of_reference_uid),
        ),
        ("/image/rows", Value::from(2)),
        ("/image/columns", Value::from(2)),
        ("/image/frames", Value::from(4)),
        ("/image/samples_per_pixel", Value::from(3)),
        ("/image/photometric_interpretation", Value::from("RGB")),
        ("/image/planar_configuration", Value::from(0)),
        ("/image/bits_allocated", Value::from(8)),
        ("/image/bits_stored", Value::from(8)),
        ("/image/high_bit", Value::from(7)),
        ("/image/pixel_representation", Value::from(0)),
        ("/pixel_data/vr", Value::from("OB")),
        ("/pixel_data/native_or_encapsulated", Value::from("native")),
        ("/pixel_data/value_length", Value::from(48)),
        ("/pixel_data/frame_count", Value::from(4)),
    ] {
        if file.pointer(pointer) != Some(&locked_value) {
            return Err(ValidateError::ManifestShape {
                path: manifest_path.to_path_buf(),
                message: "WSI manifest identity and pixel metadata must match expected_wsi_tiled_full",
            });
        }
    }
    if file.pointer("/pixel_data/frame_hashes") != expected.pointer("/pixel_data/frame_hashes") {
        return Err(ValidateError::ManifestShape {
            path: manifest_path.to_path_buf(),
            message: "WSI manifest frame hashes must match expected_wsi_tiled_full",
        });
    }
    if file
        .get("references")
        .and_then(Value::as_array)
        .is_none_or(|references| !references.is_empty())
    {
        return Err(ValidateError::ManifestShape {
            path: manifest_path.to_path_buf(),
            message: "TILED_FULL WSI references must be an empty array",
        });
    }
    Ok(())
}

fn is_manifest_uid(uid: &str) -> bool {
    !uid.is_empty()
        && uid.len() <= 64
        && uid.split('.').count() >= 2
        && uid.split('.').all(|component| {
            !component.is_empty() && component.bytes().all(|byte| byte.is_ascii_digit())
        })
}

