fn validate_family_standard_elements(
    failures: &mut Vec<String>,
    relative_path: &str,
    path: &Path,
    manifest_path: &Path,
    file: &Value,
    obj: &OpenedObject,
) -> Result<(), ValidateError> {
    match manifest_str(
        manifest_path,
        file,
        "/dicom/iod_name",
        "dicom iod_name must be a string",
    )? {
        "Secondary Capture Image" => validate_secondary_capture_standard_elements(
            failures,
            relative_path,
            manifest_path,
            file,
            obj,
        )?,
        "CT Image" => {
            validate_ct_image_standard_elements(failures, relative_path, manifest_path, file, obj)?
        }
        "Digital Mammography X-Ray Image" => validate_mammography_image_standard_elements(
            failures,
            relative_path,
            manifest_path,
            file,
            obj,
        )?,
        "Digital X-Ray Image" => {
            validate_dx_image_standard_elements(failures, relative_path, manifest_path, file, obj)?
        }
        "Ultrasound Image" => validate_ultrasound_image_standard_elements(
            failures,
            relative_path,
            manifest_path,
            file,
            obj,
        )?,
        "Ultrasound Multi-frame Image" => validate_ultrasound_multiframe_standard_elements(
            failures,
            relative_path,
            manifest_path,
            file,
            obj,
        )?,
        "Nuclear Medicine Image" => validate_nuclear_medicine_standard_elements(
            failures,
            relative_path,
            manifest_path,
            file,
            obj,
        )?,
        "PET Image" => {
            validate_pet_image_standard_elements(failures, relative_path, manifest_path, file, obj)?
        }
        "X-Ray Angiographic Image" => {
            validate_xa_image_standard_elements(failures, relative_path, manifest_path, file, obj)?
        }
        "X-Ray Radiofluoroscopic Image" => {
            validate_xrf_image_standard_elements(failures, relative_path, manifest_path, file, obj)?
        }
        "Computed Radiography Image" => {
            validate_computed_radiography_standard_elements(failures, relative_path, obj)
        }
        "MR Image" => {
            validate_mr_image_standard_elements(failures, relative_path, manifest_path, file, obj)?
        }
        "Enhanced CT Image" => validate_enhanced_ct_image_standard_elements(
            failures,
            relative_path,
            manifest_path,
            file,
            obj,
        )?,
        "Enhanced MR Image" => validate_enhanced_mr_image_standard_elements(
            failures,
            relative_path,
            manifest_path,
            file,
            obj,
        )?,
        "Enhanced PET Image" => validate_enhanced_pet_image_standard_elements(
            failures,
            relative_path,
            manifest_path,
            file,
            obj,
        )?,
        "Segmentation" => validate_segmentation_standard_elements(
            failures,
            relative_path,
            manifest_path,
            file,
            obj,
        )?,
        "Basic Text SR" | "Comprehensive SR" | "Key Object Selection Document" => {
            validate_structured_report_standard_elements(
                failures,
                relative_path,
                manifest_path,
                file,
                obj,
            )?
        }
        "Comprehensive 3D SR" => {
            if file.get("case_id").and_then(Value::as_str)
                == Some("derived/sr/comprehensive3d_scoord3d")
            {
                validate_scoord3d_standard_elements(
                    failures,
                    relative_path,
                    path,
                    manifest_path,
                    file,
                )?
            } else {
                validate_tid1500_standard_elements(
                    failures,
                    relative_path,
                    path,
                    manifest_path,
                    file,
                )?
            }
        }
        "RT Structure Set" => validate_rt_structure_set_standard_elements(
            failures,
            relative_path,
            manifest_path,
            file,
            obj,
        )?,
        "RT Dose" => {
            validate_rt_dose_standard_elements(failures, relative_path, manifest_path, file, obj)?
        }
        "Spatial Registration" => validate_spatial_registration_standard_elements(
            failures,
            relative_path,
            path,
            manifest_path,
            file,
        )?,
        "Deformable Spatial Registration" => {
            validate_deformable_spatial_registration_standard_elements(
                failures,
                relative_path,
                path,
                manifest_path,
                file,
            )?
        }
        "Color Softcopy Presentation State" => {
            validate_color_softcopy_presentation_state_standard_elements(
                failures,
                relative_path,
                path,
                manifest_path,
                file,
            )?
        }
        "Encapsulated PDF" => validate_encapsulated_pdf_standard_elements(
            failures,
            relative_path,
            manifest_path,
            file,
            obj,
        )?,
        _ => {}
    }

    Ok(())
}

fn validate_color_softcopy_presentation_state_standard_elements(
    failures: &mut Vec<String>,
    relative_path: &str,
    path: &Path,
    manifest_path: &Path,
    file: &Value,
) -> Result<(), ValidateError> {
    let expected = file
        .get("expected_color_softcopy_presentation_state")
        .ok_or(ValidateError::ManifestShape {
            path: manifest_path.to_path_buf(),
            message: "Color Softcopy Presentation State must declare expected_color_softcopy_presentation_state",
        })?;
    let source = expected.get("source").ok_or(ValidateError::ManifestShape {
        path: manifest_path.to_path_buf(),
        message: "Color Softcopy Presentation State source must be an object",
    })?;
    let expectations = validation::ColorSoftcopyPresentationStateExpectations {
        sop_class_uid: manifest_str(
            manifest_path,
            file,
            "/dicom/sop_class_uid",
            "Color Softcopy Presentation State SOP Class UID must be a string",
        )?,
        sop_instance_uid: manifest_str(
            manifest_path,
            file,
            "/uids/sop_instance_uid",
            "Color Softcopy Presentation State SOP Instance UID must be a string",
        )?,
        transfer_syntax_uid: manifest_str(
            manifest_path,
            file,
            "/dicom/transfer_syntax_uid",
            "Color Softcopy Presentation State transfer syntax UID must be a string",
        )?,
        implementation_class_uid: manifest_str(
            manifest_path,
            file,
            "/uids/implementation_class_uid",
            "Color Softcopy Presentation State implementation class UID must be a string",
        )?,
        synthetic_data: manifest_str(
            manifest_path,
            file,
            "/expected_semantics/synthetic_data",
            "Color Softcopy Presentation State Synthetic Data expectation must be a string",
        )?,
        study_instance_uid: manifest_str(
            manifest_path,
            file,
            "/uids/study_instance_uid",
            "Color Softcopy Presentation State Study UID must be a string",
        )?,
        series_instance_uid: manifest_str(
            manifest_path,
            file,
            "/uids/series_instance_uid",
            "Color Softcopy Presentation State Series UID must be a string",
        )?,
        source_study_instance_uid: manifest_str(
            manifest_path,
            source,
            "/study_instance_uid",
            "Color Softcopy Presentation State source Study UID must be a string",
        )?,
        source_series_instance_uid: manifest_str(
            manifest_path,
            source,
            "/series_instance_uid",
            "Color Softcopy Presentation State source Series UID must be a string",
        )?,
        source_sop_class_uid: manifest_str(
            manifest_path,
            source,
            "/sop_class_uid",
            "Color Softcopy Presentation State source SOP Class UID must be a string",
        )?,
        source_sop_instance_uid: manifest_str(
            manifest_path,
            source,
            "/sop_instance_uid",
            "Color Softcopy Presentation State source SOP Instance UID must be a string",
        )?,
        icc_profile_sha256: manifest_str(
            manifest_path,
            expected,
            "/icc_profile/sha256",
            "Color Softcopy Presentation State ICC profile SHA-256 must be a string",
        )?,
    };
    if let Err(error) =
        validation::validate_color_softcopy_presentation_state_file(path, &expectations)
    {
        failures.push(format!(
            "{relative_path}: color_softcopy_presentation_state_content_contract: {error}"
        ));
    }
    Ok(())
}

