#[derive(Default)]
struct NmMultiframeReportFields {
    frame_increment_pointers: Option<String>,
    energy_window_vector: Option<String>,
    detector_vector: Option<String>,
    energy_window_names: Option<String>,
    detector_start_angles_degrees: Option<String>,
    frame_dimension_tuples: Option<String>,
}

#[derive(Debug, Default, PartialEq)]
struct WaveformGroupReportSummary {
    label: String,
    shape: String,
    channel_labels: String,
    channel_source_codes: String,
    payload_length_bytes: u64,
    payload_sha256: String,
    channel_hash_count: u64,
    simultaneous_sampling: bool,
    duration_seconds: u64,
    bits_stored: u64,
    bits_allocated: u64,
    sample_interpretation: String,
    storage_vr: String,
    interleave_order: String,
    channel_count: u64,
    samples_per_channel: u64,
    sampling_frequency_hz: u64,
    legacy_channel_labels: String,
    legacy_channel_source_codes: String,
}

#[derive(Debug, Default, PartialEq)]
struct WaveformReportFields {
    iod_kind: Option<String>,
    group_count: Option<u64>,
    group_shapes: Option<String>,
    group_channel_labels: Option<String>,
    group_channel_source_codes: Option<String>,
    group_payload_lengths_bytes: Option<String>,
    group_payload_sha256_values: Option<String>,
    total_channel_count: Option<u64>,
    total_payload_length_bytes: Option<u64>,
    aggregate_payload_sha256: Option<String>,
    total_channel_hash_count: Option<u64>,
    all_groups_simultaneous_sampling: Option<bool>,
    common_duration_seconds: Option<u64>,
    channel_count: Option<u64>,
    samples_per_channel: Option<u64>,
    sampling_frequency_hz: Option<u64>,
    duration_seconds: Option<u64>,
    channel_labels: Option<String>,
    channel_source_codes: Option<String>,
    bits_allocated: Option<u64>,
    bits_stored: Option<u64>,
    sample_interpretation: Option<String>,
    storage_vr: Option<String>,
    payload_length_bytes: Option<u64>,
    payload_sha256: Option<String>,
    interleave_order: Option<String>,
    channel_hash_count: Option<u64>,
    simultaneous_sampling: Option<bool>,
    pixel_data_absent: Option<bool>,
    external_validator_disposition: Option<String>,
}

fn waveform_report_fields(
    manifest_path: &Path,
    file: &Value,
) -> Result<WaveformReportFields, ReportError> {
    let is_waveform = file
        .get("case_id")
        .and_then(Value::as_str)
        .is_some_and(|case_id| case_id.starts_with("non-image/waveform/"));
    let Some(expected) = file.get("expected_waveform") else {
        return if is_waveform {
            Err(ReportError::MetadataShape {
                path: manifest_path.to_path_buf(),
                message: "waveform file must define expected_waveform",
            })
        } else {
            Ok(WaveformReportFields::default())
        };
    };
    let groups = expected.get("multiplex_groups").and_then(Value::as_array);
    let aggregate = expected.get("aggregate");
    let absent = expected.get("absent_content");
    let group_summaries = groups.and_then(|items| {
        items
            .iter()
            .map(|group| {
                let label = group.get("label")?.as_str()?;
                let channel_count = group.get("channel_count")?.as_u64()?;
                let samples = group.get("samples_per_channel")?.as_u64()?;
                let rate = group.get("sampling_frequency_hz")?.as_u64()?;
                let channels = group.get("channels")?.as_array()?;
                let storage = group.get("storage")?;
                let labels = channels
                    .iter()
                    .map(|channel| channel.get("label")?.as_str())
                    .collect::<Option<Vec<_>>>()?;
                let source_codes = channels
                    .iter()
                    .map(|channel| {
                        let source = channel.get("source")?;
                        Some(format!(
                            "{}|{}|{}",
                            source.get("code_value")?.as_str()?,
                            source.get("coding_scheme_designator")?.as_str()?,
                            source.get("code_meaning")?.as_str()?
                        ))
                    })
                    .collect::<Option<Vec<_>>>()?;
                let bits_stored = channels
                    .iter()
                    .map(|channel| channel.get("bits_stored")?.as_u64())
                    .collect::<Option<Vec<_>>>()?;
                let channel_hashes = storage.get("channel_sha256")?.as_array()?;
                if channel_count != channels.len() as u64
                    || channel_count != channel_hashes.len() as u64
                    || bits_stored.len() != channels.len()
                {
                    return None;
                }
                let common_bits_stored = bits_stored
                    .first()
                    .copied()
                    .filter(|first| bits_stored.iter().all(|value| value == first))?;
                Some(WaveformGroupReportSummary {
                    label: label.to_string(),
                    shape: format!("{channel_count}x{samples}@{rate}Hz"),
                    channel_labels: format!("{label}[{}]", labels.join(", ")),
                    channel_source_codes: format!("{label}[{}]", source_codes.join(", ")),
                    payload_length_bytes: storage.get("payload_length_bytes")?.as_u64()?,
                    payload_sha256: storage.get("payload_sha256")?.as_str()?.to_string(),
                    channel_hash_count: channel_hashes.len() as u64,
                    simultaneous_sampling: group.get("simultaneous_sampling")?.as_bool()?,
                    duration_seconds: group.get("duration_seconds")?.as_u64()?,
                    bits_stored: common_bits_stored,
                    bits_allocated: storage.get("bits_allocated")?.as_u64()?,
                    sample_interpretation: storage
                        .get("sample_interpretation")?
                        .as_str()?
                        .to_string(),
                    storage_vr: storage.get("data_vr")?.as_str()?.to_string(),
                    interleave_order: storage.get("interleave_order")?.as_str()?.to_string(),
                    channel_count,
                    samples_per_channel: samples,
                    sampling_frequency_hz: rate,
                    legacy_channel_labels: labels.join("; "),
                    legacy_channel_source_codes: source_codes.join("; "),
                })
            })
            .collect::<Option<Vec<_>>>()
    });
    let single_group = group_summaries
        .as_ref()
        .filter(|summaries| summaries.len() == 1)
        .and_then(|summaries| summaries.first());
    let group_shapes = group_summaries.as_ref().map(|summaries| {
        if let [summary] = summaries.as_slice() {
            return format!("{}:{}", summary.label, summary.shape);
        }
        summaries
            .iter()
            .map(|summary| summary.shape.as_str())
            .collect::<Vec<_>>()
            .join("; ")
    });
    let group_channel_labels = group_summaries.as_ref().map(|summaries| {
        summaries
            .iter()
            .map(|summary| summary.channel_labels.as_str())
            .collect::<Vec<_>>()
            .join("; ")
    });
    let group_channel_source_codes = group_summaries.as_ref().map(|summaries| {
        summaries
            .iter()
            .map(|summary| summary.channel_source_codes.as_str())
            .collect::<Vec<_>>()
            .join("; ")
    });
    let group_payload_lengths_bytes = group_summaries.as_ref().map(|summaries| {
        summaries
            .iter()
            .map(|summary| summary.payload_length_bytes.to_string())
            .collect::<Vec<_>>()
            .join("; ")
    });
    let group_payload_sha256_values = group_summaries.as_ref().map(|summaries| {
        summaries
            .iter()
            .map(|summary| summary.payload_sha256.as_str())
            .collect::<Vec<_>>()
            .join("; ")
    });
    let total_channel_hash_count = group_summaries.as_ref().map(|summaries| {
        summaries
            .iter()
            .map(|summary| summary.channel_hash_count)
            .sum()
    });
    let all_groups_simultaneous_sampling = group_summaries.as_ref().map(|summaries| {
        summaries
            .iter()
            .all(|summary| summary.simultaneous_sampling)
    });

    let fields = WaveformReportFields {
        iod_kind: expected
            .get("iod_kind")
            .and_then(Value::as_str)
            .map(str::to_string),
        group_count: aggregate
            .and_then(|value| value.get("group_count"))
            .and_then(Value::as_u64),
        group_shapes,
        group_channel_labels,
        group_channel_source_codes,
        group_payload_lengths_bytes,
        group_payload_sha256_values,
        total_channel_count: aggregate
            .and_then(|value| value.get("total_channel_count"))
            .and_then(Value::as_u64),
        total_payload_length_bytes: aggregate
            .and_then(|value| value.get("total_payload_length_bytes"))
            .and_then(Value::as_u64),
        aggregate_payload_sha256: aggregate
            .and_then(|value| value.get("aggregate_payload_sha256"))
            .and_then(Value::as_str)
            .map(str::to_string),
        total_channel_hash_count,
        all_groups_simultaneous_sampling,
        common_duration_seconds: aggregate
            .and_then(|value| value.get("common_duration_seconds"))
            .and_then(Value::as_u64),
        channel_count: single_group.map(|summary| summary.channel_count),
        samples_per_channel: single_group.map(|summary| summary.samples_per_channel),
        sampling_frequency_hz: single_group.map(|summary| summary.sampling_frequency_hz),
        duration_seconds: single_group.map(|summary| summary.duration_seconds),
        channel_labels: single_group.map(|summary| summary.legacy_channel_labels.clone()),
        channel_source_codes: single_group
            .map(|summary| summary.legacy_channel_source_codes.clone()),
        bits_allocated: single_group.map(|summary| summary.bits_allocated),
        bits_stored: single_group.map(|summary| summary.bits_stored),
        sample_interpretation: single_group.map(|summary| summary.sample_interpretation.clone()),
        storage_vr: single_group.map(|summary| summary.storage_vr.clone()),
        payload_length_bytes: single_group.map(|summary| summary.payload_length_bytes),
        payload_sha256: single_group.map(|summary| summary.payload_sha256.clone()),
        interleave_order: single_group.map(|summary| summary.interleave_order.clone()),
        channel_hash_count: single_group.map(|summary| summary.channel_hash_count),
        simultaneous_sampling: single_group.map(|summary| summary.simultaneous_sampling),
        pixel_data_absent: absent
            .and_then(|value| value.get("pixel_data"))
            .and_then(Value::as_bool),
        external_validator_disposition: Some(
            "external conformance evidence not embedded; run conformance separately".to_string(),
        ),
    };
    let complete = fields.iod_kind.is_some()
        && fields.group_count.is_some()
        && fields
            .group_shapes
            .as_deref()
            .is_some_and(|value| !value.is_empty())
        && fields
            .group_channel_labels
            .as_deref()
            .is_some_and(|value| !value.is_empty())
        && fields
            .group_channel_source_codes
            .as_deref()
            .is_some_and(|value| !value.is_empty())
        && fields.group_payload_lengths_bytes.is_some()
        && fields.group_payload_sha256_values.is_some()
        && fields.total_channel_count.is_some()
        && fields.total_payload_length_bytes.is_some()
        && fields.aggregate_payload_sha256.is_some()
        && fields.total_channel_hash_count.is_some()
        && fields.all_groups_simultaneous_sampling.is_some()
        && fields.common_duration_seconds.is_some()
        && fields.pixel_data_absent.is_some()
        && groups.is_some_and(|items| fields.group_count == Some(items.len() as u64))
        && group_summaries.as_ref().is_some_and(|summaries| {
            fields.total_channel_count
                == Some(summaries.iter().map(|summary| summary.channel_count).sum())
                && fields.total_payload_length_bytes
                    == Some(
                        summaries
                            .iter()
                            .map(|summary| summary.payload_length_bytes)
                            .sum(),
                    )
                && fields.total_channel_hash_count
                    == Some(
                        summaries
                            .iter()
                            .map(|summary| summary.channel_hash_count)
                            .sum(),
                    )
                && summaries
                    .iter()
                    .all(|summary| Some(summary.duration_seconds) == fields.common_duration_seconds)
        })
        && aggregate
            .and_then(|value| value.get("group_payload_sha256"))
            .and_then(Value::as_array)
            .is_some_and(|hashes| {
                group_summaries.as_ref().is_some_and(|summaries| {
                    hashes.len() == summaries.len()
                        && hashes.iter().zip(summaries).all(|(hash, summary)| {
                            hash.as_str() == Some(summary.payload_sha256.as_str())
                        })
                })
            });
    if !complete {
        return Err(ReportError::MetadataShape {
            path: manifest_path.to_path_buf(),
            message: "expected_waveform must define the complete report contract",
        });
    }
    Ok(fields)
}

#[derive(Debug, Default, PartialEq)]
struct RtImageReportFields {
    image_type: Option<String>,
    label: Option<String>,
    plane: Option<String>,
    pixel_spacing_mm: Option<String>,
    position_mm: Option<String>,
    dimensions: Option<String>,
    bit_contract: Option<String>,
    payload_sha256: Option<String>,
    plan_reference_identity: Option<String>,
    referenced_beam_number: Option<u64>,
    referenced_fraction_group_number: Option<u64>,
    radiation_machine_sad_mm: Option<u64>,
    sid_mm: Option<u64>,
    reference_closure: Option<bool>,
    pixel_disposition: Option<String>,
    external_validator_disposition: Option<String>,
}

fn rt_image_report_fields(
    manifest_path: &Path,
    file: &Value,
) -> Result<RtImageReportFields, ReportError> {
    let is_rt_image =
        file.get("case_id").and_then(Value::as_str) == Some("non-image/rt/image_linked");
    let Some(expected) = file.get("expected_rt_image") else {
        return if is_rt_image {
            Err(ReportError::MetadataShape {
                path: manifest_path.to_path_buf(),
                message: "generated linked RT Image must define expected_rt_image",
            })
        } else {
            Ok(RtImageReportFields::default())
        };
    };
    if !is_rt_image {
        return Err(ReportError::MetadataShape {
            path: manifest_path.to_path_buf(),
            message: "expected_rt_image is only valid for non-image/rt/image_linked",
        });
    }

    let image_type = expected
        .pointer("/image/image_type")
        .and_then(Value::as_array)
        .and_then(|values| {
            values
                .iter()
                .map(Value::as_str)
                .collect::<Option<Vec<_>>>()
                .map(|values| values.join("\\"))
        });
    let pair = |pointer: &str| {
        expected
            .pointer(pointer)
            .and_then(Value::as_array)
            .and_then(|values| {
                (values.len() == 2).then(|| {
                    values
                        .iter()
                        .map(|value| {
                            value
                                .as_i64()
                                .map(|value| value.to_string())
                                .or_else(|| value.as_f64().map(|value| value.to_string()))
                        })
                        .collect::<Option<Vec<_>>>()
                        .map(|values| values.join("\\"))
                })?
            })
    };
    let plan_reference = expected.get("plan_reference");
    let plan_reference_identity = plan_reference.and_then(|reference| {
        Some(format!(
            "{}|{}|{}|study={}|series={}|class={}|instance={}|for={}",
            reference.get("source_case_id")?.as_str()?,
            reference.get("source_path")?.as_str()?,
            reference.get("source_sha256")?.as_str()?,
            reference.get("study_instance_uid")?.as_str()?,
            reference.get("series_instance_uid")?.as_str()?,
            reference.get("sop_class_uid")?.as_str()?,
            reference.get("sop_instance_uid")?.as_str()?,
            reference.get("frame_of_reference_uid")?.as_str()?,
        ))
    });
    let manifest_reference = file
        .get("references")
        .and_then(Value::as_array)
        .and_then(|items| (items.len() == 1).then(|| &items[0]));
    let reference_closure = plan_reference
        .zip(manifest_reference)
        .map(|(locked, actual)| {
            [
                "relationship",
                "source_case_id",
                "source_path",
                "series_instance_uid",
                "sop_class_uid",
                "sop_instance_uid",
            ]
            .iter()
            .all(|field| locked.get(field) == actual.get(field))
                && locked.get("study_instance_uid") == expected.get("study_instance_uid")
                && locked.get("frame_of_reference_uid") == expected.get("frame_of_reference_uid")
                && locked
                    .get("source_sha256")
                    .and_then(Value::as_str)
                    .is_some_and(|hash| hash.len() == 64)
        });
    let storage = expected.get("storage");
    let dimensions = storage.and_then(|storage| {
        Some(format!(
            "{}x{}x{}",
            storage.get("rows")?.as_u64()?,
            storage.get("columns")?.as_u64()?,
            storage.get("frames")?.as_u64()?
        ))
    });
    let bit_contract = storage.and_then(|storage| {
        Some(format!(
            "{}/{}/{}/u{}",
            storage.get("bits_allocated")?.as_u64()?,
            storage.get("bits_stored")?.as_u64()?,
            storage.get("high_bit")?.as_u64()?,
            storage.get("pixel_representation")?.as_u64()?
        ))
    });
    let pixel_disposition = storage.and_then(|storage| {
        Some(format!(
            "{} {} / {} bytes / {} padding bytes",
            storage.get("encoding")?.as_str()?,
            storage.get("data_vr")?.as_str()?,
            storage.get("payload_length_bytes")?.as_u64()?,
            storage.get("value_field_padding_bytes")?.as_u64()?
        ))
    });
    let fields = RtImageReportFields {
        image_type,
        label: expected
            .pointer("/image/label")
            .and_then(Value::as_str)
            .map(str::to_string),
        plane: expected
            .pointer("/image/plane")
            .and_then(Value::as_str)
            .map(str::to_string),
        pixel_spacing_mm: pair("/image/image_plane_pixel_spacing_mm"),
        position_mm: pair("/image/position_mm"),
        dimensions,
        bit_contract,
        payload_sha256: storage
            .and_then(|storage| storage.get("payload_sha256"))
            .and_then(Value::as_str)
            .map(str::to_string),
        plan_reference_identity,
        referenced_beam_number: expected
            .pointer("/linkage/referenced_beam_number")
            .and_then(Value::as_u64),
        referenced_fraction_group_number: expected
            .pointer("/linkage/referenced_fraction_group_number")
            .and_then(Value::as_u64),
        radiation_machine_sad_mm: expected
            .pointer("/image/radiation_machine_sad_mm")
            .and_then(Value::as_u64),
        sid_mm: expected
            .pointer("/image/rt_image_sid_mm")
            .and_then(Value::as_u64),
        reference_closure,
        pixel_disposition,
        external_validator_disposition: Some(
            "external conformance evidence not embedded; run conformance separately".to_string(),
        ),
    };
    let exact_pixels = serde_json::json!([
        0, 17, 34, 51, 68, 85, 102, 119, 136, 153, 170, 187, 204, 221, 238, 255
    ]);
    let absent = expected.get("absent_content").and_then(Value::as_object);
    let complete = expected.get("iod_kind").and_then(Value::as_str) == Some("rt_image")
        && expected.get("sop_class_uid").and_then(Value::as_str)
            == Some("1.2.840.10008.5.1.4.1.1.481.1")
        && expected.get("iod_name").and_then(Value::as_str) == Some("RT Image")
        && expected.get("modality").and_then(Value::as_str) == Some("RTIMAGE")
        && expected.get("transfer_syntax_uid").and_then(Value::as_str)
            == Some("1.2.840.10008.1.2.1")
        && fields.image_type.as_deref() == Some("DERIVED\\SECONDARY\\DRR")
        && fields.label.as_deref() == Some("DTS_DRR")
        && fields.plane.as_deref() == Some("NORMAL")
        && expected
            .pointer("/image/conversion_type")
            .and_then(Value::as_str)
            == Some("WSD")
        && expected
            .pointer("/image/xray_image_receptor_angle_degrees")
            .and_then(Value::as_i64)
            == Some(0)
        && fields.pixel_spacing_mm.as_deref() == Some("1\\1")
        && fields.position_mm.as_deref() == Some("-1.5\\1.5")
        && expected
            .pointer("/image/radiation_machine_name")
            .and_then(Value::as_str)
            == Some("DTS_LINAC")
        && fields.radiation_machine_sad_mm == Some(1000)
        && fields.sid_mm == Some(1500)
        && expected
            .pointer("/image/primary_dosimeter_unit")
            .and_then(Value::as_str)
            == Some("MU")
        && fields.dimensions.as_deref() == Some("4x4x1")
        && storage
            .and_then(|value| value.get("samples_per_pixel"))
            .and_then(Value::as_u64)
            == Some(1)
        && storage
            .and_then(|value| value.get("photometric_interpretation"))
            .and_then(Value::as_str)
            == Some("MONOCHROME2")
        && fields.bit_contract.as_deref() == Some("8/8/7/u0")
        && fields.pixel_disposition.as_deref() == Some("native OB / 16 bytes / 0 padding bytes")
        && storage
            .and_then(|value| value.get("pixel_value_formula"))
            .and_then(Value::as_str)
            == Some("17 * (4 * r + c)")
        && storage.and_then(|value| value.get("pixel_values")) == Some(&exact_pixels)
        && storage
            .and_then(|value| value.get("pixel_min"))
            .and_then(Value::as_u64)
            == Some(0)
        && storage
            .and_then(|value| value.get("pixel_max"))
            .and_then(Value::as_u64)
            == Some(255)
        && fields.payload_sha256.as_deref()
            == Some("a8faed6abbf35c12a4b26e40f6feb19d736d90045c83b9f9a31f638d323e6811")
        && storage
            .and_then(|value| value.get("decoded_pixels_sha256"))
            .and_then(Value::as_str)
            == fields.payload_sha256.as_deref()
        && plan_reference
            .and_then(|value| value.get("relationship"))
            .and_then(Value::as_str)
            == Some("referenced_rt_plan")
        && plan_reference
            .and_then(|value| value.get("source_case_id"))
            .and_then(Value::as_str)
            == Some("non-image/rt/plan_linked")
        && plan_reference
            .and_then(|value| value.get("source_path"))
            .and_then(Value::as_str)
            == Some("non-image/rt/plan_linked/instance.dcm")
        && plan_reference
            .and_then(|value| value.get("sop_class_uid"))
            .and_then(Value::as_str)
            == Some("1.2.840.10008.5.1.4.1.1.481.5")
        && fields.referenced_beam_number == Some(1)
        && fields.referenced_fraction_group_number == Some(1)
        && fields.reference_closure == Some(true)
        && absent.is_some_and(|values| {
            values.len() == 19 && values.values().all(|v| v.as_bool() == Some(true))
        });
    if !complete {
        return Err(ReportError::MetadataShape {
            path: manifest_path.to_path_buf(),
            message: "expected_rt_image must define the complete linked Image report contract",
        });
    }
    Ok(fields)
}

fn rt_reference_identity(reference: &Value) -> Option<String> {
    Some(format!(
        "{}|{}|{}|study={}|series={}|class={}|instance={}|for={}",
        reference.get("source_case_id")?.as_str()?,
        reference.get("source_path")?.as_str()?,
        reference.get("source_sha256")?.as_str()?,
        reference.get("study_instance_uid")?.as_str()?,
        reference.get("series_instance_uid")?.as_str()?,
        reference.get("sop_class_uid")?.as_str()?,
        reference.get("sop_instance_uid")?.as_str()?,
        reference.get("frame_of_reference_uid")?.as_str()?,
    ))
}

fn rt_code_summary(code: Option<&Value>) -> Option<String> {
    let code = code?;
    Some(format!(
        "{}|{}|{}",
        code.get("code_value")?.as_str()?,
        code.get("coding_scheme_designator")?.as_str()?,
        code.get("code_meaning")?.as_str()?,
    ))
}

fn rt_device_identity(device: Option<&Value>) -> Option<String> {
    let device = device?;
    Some(format!(
        "{}|{}|{}|{}|{}",
        device.get("manufacturer")?.as_str()?,
        device.get("model_name")?.as_str()?,
        device.get("device_label")?.as_str()?,
        device.get("serial_number")?.as_str()?,
        device.get("device_alternate_identifier")?.as_str()?,
    ))
}

fn is_lowerhex_sha256(value: Option<&Value>) -> bool {
    value.and_then(Value::as_str).is_some_and(|hash| {
        hash.len() == 64
            && hash
                .bytes()
                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    })
}

#[derive(Debug, Default, PartialEq)]
struct RtRadiationReportFields {
    iod_kind: Option<String>,
    label: Option<String>,
    content_detail: Option<String>,
    record_flag: Option<String>,
    treatment_technique: Option<String>,
    device_identity: Option<String>,
    dosimeter_unit: Option<String>,
    treatment_position_count: Option<u64>,
    treatment_position_indices: Option<String>,
    control_point_count: Option<u64>,
    control_point_indices: Option<String>,
    meterset_range: Option<String>,
    definition_source_identity: Option<String>,
    reference_closure: Option<bool>,
    pixel_data_absent: Option<bool>,
    external_validator_disposition: Option<String>,
}

fn rt_radiation_report_fields(
    manifest_path: &Path,
    file: &Value,
) -> Result<RtRadiationReportFields, ReportError> {
    const CASE_ID: &str = "non-image/rt/carm_photon_electron_radiation_minimal";
    let is_case = file.get("case_id").and_then(Value::as_str) == Some(CASE_ID);
    let Some(expected) = file.get("expected_rt_radiation") else {
        return if is_case {
            Err(ReportError::MetadataShape {
                path: manifest_path.to_path_buf(),
                message: "generated C-Arm Photon-Electron Radiation must define expected_rt_radiation",
            })
        } else {
            Ok(RtRadiationReportFields::default())
        };
    };
    if !is_case {
        return Err(ReportError::MetadataShape {
            path: manifest_path.to_path_buf(),
            message: "expected_rt_radiation is only valid for non-image/rt/carm_photon_electron_radiation_minimal",
        });
    }
    let positions = expected
        .get("treatment_positions")
        .and_then(Value::as_array);
    let control_points = expected.get("control_points").and_then(Value::as_array);
    let join_indices = |items: Option<&Vec<Value>>, field: &str| {
        items.and_then(|items| {
            items
                .iter()
                .map(|item| item.get(field)?.as_u64().map(|n| n.to_string()))
                .collect::<Option<Vec<_>>>()
                .map(|v| v.join("; "))
        })
    };
    let definition = expected.get("definition_source");
    let study_uid = expected.get("study_instance_uid");
    let frame_uid = expected.get("frame_of_reference_uid");
    let fields = RtRadiationReportFields {
        iod_kind: expected
            .get("iod_kind")
            .and_then(Value::as_str)
            .map(str::to_string),
        label: expected
            .pointer("/content/user_content_label")
            .and_then(Value::as_str)
            .map(str::to_string),
        content_detail: expected
            .pointer("/content/physical_and_geometric_content_detail_flag")
            .and_then(Value::as_str)
            .map(str::to_string),
        record_flag: expected
            .pointer("/content/rt_record_flag")
            .and_then(Value::as_str)
            .map(str::to_string),
        treatment_technique: rt_code_summary(expected.pointer("/content/treatment_technique")),
        device_identity: rt_device_identity(expected.get("device")),
        dosimeter_unit: rt_code_summary(expected.get("dosimeter_unit")),
        treatment_position_count: positions.map(|items| items.len() as u64),
        treatment_position_indices: join_indices(positions, "treatment_position_index"),
        control_point_count: control_points.map(|items| items.len() as u64),
        control_point_indices: join_indices(control_points, "rt_control_point_index"),
        meterset_range: control_points.and_then(|items| {
            Some(format!(
                "{}..{}",
                items.first()?.get("cumulative_meterset")?.as_u64()?,
                items.last()?.get("cumulative_meterset")?.as_u64()?
            ))
        }),
        definition_source_identity: definition.and_then(rt_reference_identity),
        reference_closure: definition
            .zip(file.get("references").and_then(Value::as_array))
            .map(|(reference, manifest)| {
                manifest.len() == 1
                    && [
                        "relationship",
                        "source_case_id",
                        "source_path",
                        "series_instance_uid",
                        "sop_class_uid",
                        "sop_instance_uid",
                    ]
                    .iter()
                    .all(|field| reference.get(field) == manifest[0].get(field))
                    && is_lowerhex_sha256(reference.get("source_sha256"))
                    && reference.get("study_instance_uid") == study_uid
                    && reference.get("frame_of_reference_uid") == frame_uid
            }),
        pixel_data_absent: expected
            .pointer("/absent_content/pixel_data")
            .and_then(Value::as_bool),
        external_validator_disposition: Some(
            "external conformance evidence not embedded; run conformance separately".to_string(),
        ),
    };
    let complete = fields.iod_kind.as_deref() == Some("carm_photon_electron_radiation")
        && fields.label.as_deref() == Some("DTS_RADIATION")
        && fields.content_detail.as_deref() == Some("IDENT_ONLY")
        && fields.record_flag.as_deref() == Some("NO")
        && fields.treatment_technique.as_deref() == Some("130102|DCM|Static Beam")
        && fields.device_identity.as_deref()
            == Some("dicom-test-suite|DTS C-Arm LINAC|DTS_LINAC|DTS-LINAC-001|")
        && fields.dosimeter_unit.as_deref() == Some("{MU}|UCUM|Monitor Units")
        && fields.treatment_position_count == Some(1)
        && fields.treatment_position_indices.as_deref() == Some("1")
        && fields.control_point_count == Some(2)
        && fields.control_point_indices.as_deref() == Some("1; 2")
        && fields.meterset_range.as_deref() == Some("0..100")
        && fields.definition_source_identity.is_some()
        && fields.reference_closure == Some(true)
        && fields.pixel_data_absent == Some(true);
    if !complete {
        return Err(ReportError::MetadataShape {
            path: manifest_path.to_path_buf(),
            message: "expected_rt_radiation must define the complete C-Arm Radiation report contract",
        });
    }
    Ok(fields)
}

#[derive(Debug, Default, PartialEq)]
struct RtRadiationSetReportFields {
    iod_kind: Option<String>,
    label: Option<String>,
    intent: Option<String>,
    intended_fraction_count: Option<u64>,
    device_identity: Option<String>,
    definition_source_identity: Option<String>,
    radiation_reference_identities: Option<String>,
    treatment_position_group_count: Option<u64>,
    treatment_position_group_labels: Option<String>,
    common_instance_reference_count: Option<u64>,
    reference_closure: Option<bool>,
    dose_contribution_absent: Option<bool>,
    pixel_data_absent: Option<bool>,
    external_validator_disposition: Option<String>,
}

fn rt_radiation_set_report_fields(
    manifest_path: &Path,
    file: &Value,
) -> Result<RtRadiationSetReportFields, ReportError> {
    const CASE_ID: &str = "non-image/rt/radiation_set_minimal";
    let is_case = file.get("case_id").and_then(Value::as_str) == Some(CASE_ID);
    let Some(expected) = file.get("expected_rt_radiation_set") else {
        return if is_case {
            Err(ReportError::MetadataShape {
                path: manifest_path.to_path_buf(),
                message: "generated RT Radiation Set must define expected_rt_radiation_set",
            })
        } else {
            Ok(RtRadiationSetReportFields::default())
        };
    };
    if !is_case {
        return Err(ReportError::MetadataShape {
            path: manifest_path.to_path_buf(),
            message: "expected_rt_radiation_set is only valid for non-image/rt/radiation_set_minimal",
        });
    }
    let radiation_refs = expected
        .get("radiation_references")
        .and_then(Value::as_array);
    let groups = expected
        .get("treatment_position_groups")
        .and_then(Value::as_array);
    let common_refs = expected
        .get("common_instance_references")
        .and_then(Value::as_array);
    let identities = |items: Option<&Vec<Value>>| {
        items.and_then(|items| {
            items
                .iter()
                .map(rt_reference_identity)
                .collect::<Option<Vec<_>>>()
                .map(|v| v.join("; "))
        })
    };
    let manifest_refs = file.get("references").and_then(Value::as_array);
    let study_uid = expected.get("study_instance_uid");
    let frame_uid = expected.get("frame_of_reference_uid");
    let fields = RtRadiationSetReportFields {
        iod_kind: expected
            .get("iod_kind")
            .and_then(Value::as_str)
            .map(str::to_string),
        label: expected
            .pointer("/content/user_content_label")
            .and_then(Value::as_str)
            .map(str::to_string),
        intent: expected
            .pointer("/content/intent")
            .and_then(Value::as_str)
            .map(str::to_string),
        intended_fraction_count: expected
            .pointer("/content/intended_number_of_fractions")
            .and_then(Value::as_u64),
        device_identity: rt_device_identity(expected.get("linked_radiation_device")),
        definition_source_identity: expected
            .get("definition_source")
            .and_then(rt_reference_identity),
        radiation_reference_identities: identities(radiation_refs),
        treatment_position_group_count: groups.map(|items| items.len() as u64),
        treatment_position_group_labels: groups.and_then(|items| {
            items
                .iter()
                .map(|item| item.get("label")?.as_str().map(str::to_string))
                .collect::<Option<Vec<_>>>()
                .map(|v| v.join("; "))
        }),
        common_instance_reference_count: common_refs.map(|items| items.len() as u64),
        reference_closure: expected
            .get("definition_source")
            .zip(radiation_refs)
            .zip(manifest_refs)
            .map(|((definition, radiation), manifest)| {
                let expected_refs = std::iter::once(definition)
                    .chain(radiation.iter())
                    .collect::<Vec<_>>();
                let locked_identity = |reference: &&Value| {
                    is_lowerhex_sha256(reference.get("source_sha256"))
                        && reference.get("study_instance_uid") == study_uid
                        && reference.get("frame_of_reference_uid") == frame_uid
                };
                let source_identities_locked = expected_refs.iter().all(locked_identity);
                let common_match = common_refs.is_some_and(|common| {
                    common.len() == 2
                        && expected_refs.iter().zip(common).all(|(locked, mirrored)| {
                            [
                                "relationship",
                                "source_case_id",
                                "source_path",
                                "source_sha256",
                                "study_instance_uid",
                                "series_instance_uid",
                                "sop_class_uid",
                                "sop_instance_uid",
                                "frame_of_reference_uid",
                            ]
                            .iter()
                            .all(|field| locked.get(field) == mirrored.get(field))
                        })
                });
                let group_match = groups.is_some_and(|groups| {
                    groups.len() == 1
                        && groups[0]
                            .get("radiation_references")
                            .and_then(Value::as_array)
                            .is_some_and(|group_refs| {
                                group_refs.len() == 1
                                    && radiation.first().is_some_and(|locked| {
                                        [
                                            "relationship",
                                            "source_case_id",
                                            "source_path",
                                            "source_sha256",
                                            "study_instance_uid",
                                            "series_instance_uid",
                                            "sop_class_uid",
                                            "sop_instance_uid",
                                            "frame_of_reference_uid",
                                        ]
                                        .iter()
                                        .all(|field| locked.get(field) == group_refs[0].get(field))
                                    })
                            })
                });
                source_identities_locked
                    && common_match
                    && group_match
                    && expected_refs.len() == 2
                    && manifest.len() == 2
                    && expected_refs.iter().zip(manifest).all(|(locked, actual)| {
                        [
                            "relationship",
                            "source_case_id",
                            "source_path",
                            "series_instance_uid",
                            "sop_class_uid",
                            "sop_instance_uid",
                        ]
                        .iter()
                        .all(|field| locked.get(field) == actual.get(field))
                            && is_lowerhex_sha256(locked.get("source_sha256"))
                    })
            }),
        dose_contribution_absent: expected
            .pointer("/absent_content/rt_dose_contribution_module")
            .and_then(Value::as_bool),
        pixel_data_absent: expected
            .pointer("/absent_content/pixel_data")
            .and_then(Value::as_bool),
        external_validator_disposition: Some(
            "external conformance evidence not embedded; run conformance separately".to_string(),
        ),
    };
    let complete = fields.iod_kind.as_deref() == Some("rt_radiation_set")
        && fields.label.as_deref() == Some("DTS_RADSET")
        && fields.intent.as_deref() == Some("TREATMENT")
        && fields.intended_fraction_count == Some(1)
        && fields.device_identity.as_deref()
            == Some("dicom-test-suite|DTS C-Arm LINAC|DTS_LINAC|DTS-LINAC-001|")
        && fields.definition_source_identity.is_some()
        && fields.radiation_reference_identities.is_some()
        && fields.treatment_position_group_count == Some(1)
        && fields.treatment_position_group_labels.as_deref() == Some("DTS_TPG_1")
        && fields.common_instance_reference_count == Some(2)
        && fields.reference_closure == Some(true)
        && fields.dose_contribution_absent == Some(true)
        && fields.pixel_data_absent == Some(true);
    if !complete {
        return Err(ReportError::MetadataShape {
            path: manifest_path.to_path_buf(),
            message: "expected_rt_radiation_set must define the complete RT Radiation Set report contract",
        });
    }
    Ok(fields)
}

#[derive(Debug, Default, PartialEq)]
struct RtPlanReportFields {
    label: Option<String>,
    geometry: Option<String>,
    fraction_group_count: Option<u64>,
    fraction_group_numbers: Option<String>,
    beam_count: Option<u64>,
    beam_numbers: Option<String>,
    beam_names: Option<String>,
    beam_types: Option<String>,
    radiation_types: Option<String>,
    control_point_count: Option<u64>,
    control_point_indices: Option<String>,
    meterset_range: Option<String>,
    structure_set_reference_identity: Option<String>,
    dose_reference_identity: Option<String>,
    reference_closure: Option<bool>,
    pixel_data_absent: Option<bool>,
    external_validator_disposition: Option<String>,
}

fn rt_plan_report_fields(
    manifest_path: &Path,
    file: &Value,
) -> Result<RtPlanReportFields, ReportError> {
    let is_rt_plan =
        file.get("case_id").and_then(Value::as_str) == Some("non-image/rt/plan_linked");
    let Some(expected) = file.get("expected_rt_plan") else {
        return if is_rt_plan {
            Err(ReportError::MetadataShape {
                path: manifest_path.to_path_buf(),
                message: "generated linked RT Plan must define expected_rt_plan",
            })
        } else {
            Ok(RtPlanReportFields::default())
        };
    };
    if !is_rt_plan {
        return Err(ReportError::MetadataShape {
            path: manifest_path.to_path_buf(),
            message: "expected_rt_plan is only valid for non-image/rt/plan_linked",
        });
    }

    let fraction_groups = expected.get("fraction_groups").and_then(Value::as_array);
    let beams = expected.get("beams").and_then(Value::as_array);
    let references = expected.get("references").and_then(Value::as_array);
    let control_points = beams
        .and_then(|items| items.first())
        .and_then(|beam| beam.get("control_points"))
        .and_then(Value::as_array);
    let join_u64 = |items: Option<&Vec<Value>>, field: &str| {
        items.and_then(|values| {
            values
                .iter()
                .map(|value| value.get(field)?.as_u64().map(|value| value.to_string()))
                .collect::<Option<Vec<_>>>()
                .map(|values| values.join("; "))
        })
    };
    let join_str = |items: Option<&Vec<Value>>, field: &str| {
        items.and_then(|values| {
            values
                .iter()
                .map(|value| value.get(field)?.as_str().map(str::to_string))
                .collect::<Option<Vec<_>>>()
                .map(|values| values.join("; "))
        })
    };
    let reference_identity = |relationship: &str| {
        references
            .and_then(|items| {
                items.iter().find(|reference| {
                    reference.get("relationship").and_then(Value::as_str) == Some(relationship)
                })
            })
            .and_then(|reference| {
                Some(format!(
                    "{}|{}|{}|study={}|series={}|class={}|instance={}|for={}",
                    reference.get("source_case_id")?.as_str()?,
                    reference.get("source_path")?.as_str()?,
                    reference.get("source_sha256")?.as_str()?,
                    reference.get("study_instance_uid")?.as_str()?,
                    reference.get("series_instance_uid")?.as_str()?,
                    reference.get("sop_class_uid")?.as_str()?,
                    reference.get("sop_instance_uid")?.as_str()?,
                    reference.get("frame_of_reference_uid")?.as_str()?,
                ))
            })
    };
    let structure_set_reference_identity = reference_identity("referenced_structure_set");
    let dose_reference_identity = reference_identity("referenced_dose");
    let manifest_references = file.get("references").and_then(Value::as_array);
    let reference_closure = references
        .zip(manifest_references)
        .map(|(expected, actual)| {
            expected.len() == 2
                && actual.len() == 2
                && expected.iter().zip(actual).all(|(locked, manifest)| {
                    [
                        "relationship",
                        "source_case_id",
                        "source_path",
                        "series_instance_uid",
                        "sop_class_uid",
                        "sop_instance_uid",
                    ]
                    .iter()
                    .all(|field| locked.get(field) == manifest.get(field))
                        && locked.get("study_instance_uid")
                            == expected
                                .first()
                                .and_then(|_| file.pointer("/expected_rt_plan/study_instance_uid"))
                        && locked.get("frame_of_reference_uid")
                            == expected.first().and_then(|_| {
                                file.pointer("/expected_rt_plan/frame_of_reference_uid")
                            })
                        && locked
                            .get("source_sha256")
                            .and_then(Value::as_str)
                            .is_some_and(|hash| hash.len() == 64)
                })
        });
    let control_point_count = beams.and_then(|items| {
        items
            .iter()
            .map(|beam| beam.get("number_of_control_points")?.as_u64())
            .collect::<Option<Vec<_>>>()
            .map(|counts| counts.into_iter().sum())
    });
    let meterset_range = control_points.and_then(|items| {
        Some(format!(
            "{}..{}",
            items.first()?.get("cumulative_meterset_weight")?.as_u64()?,
            items.last()?.get("cumulative_meterset_weight")?.as_u64()?
        ))
    });
    let fields = RtPlanReportFields {
        label: expected
            .pointer("/plan/label")
            .and_then(Value::as_str)
            .map(str::to_string),
        geometry: expected
            .pointer("/plan/geometry")
            .and_then(Value::as_str)
            .map(str::to_string),
        fraction_group_count: fraction_groups.map(|items| items.len() as u64),
        fraction_group_numbers: join_u64(fraction_groups, "fraction_group_number"),
        beam_count: beams.map(|items| items.len() as u64),
        beam_numbers: join_u64(beams, "beam_number"),
        beam_names: join_str(beams, "beam_name"),
        beam_types: join_str(beams, "beam_type"),
        radiation_types: join_str(beams, "radiation_type"),
        control_point_count,
        control_point_indices: join_u64(control_points, "control_point_index"),
        meterset_range,
        structure_set_reference_identity,
        dose_reference_identity,
        reference_closure,
        pixel_data_absent: expected
            .pointer("/absent_content/pixel_data")
            .and_then(Value::as_bool),
        external_validator_disposition: Some(
            "external conformance evidence not embedded; run conformance separately".to_string(),
        ),
    };
    let complete = fields.label.is_some()
        && fields.geometry.is_some()
        && fields.fraction_group_count == Some(1)
        && fields.fraction_group_numbers.as_deref() == Some("1")
        && fields.beam_count == Some(1)
        && fields.beam_numbers.as_deref() == Some("1")
        && fields.beam_names.as_deref() == Some("DTS_STATIC_AP")
        && fields.beam_types.as_deref() == Some("STATIC")
        && fields.radiation_types.as_deref() == Some("PHOTON")
        && fields.control_point_count == Some(2)
        && fields.control_point_indices.as_deref() == Some("0; 1")
        && fields.meterset_range.as_deref() == Some("0..1")
        && fields.structure_set_reference_identity.is_some()
        && fields.dose_reference_identity.is_some()
        && fields.reference_closure == Some(true)
        && fields.pixel_data_absent == Some(true)
        && control_points.is_some_and(|items| items.len() == 2)
        && beams.is_some_and(|items| {
            items.first().is_some_and(|beam| {
                beam.get("number_of_control_points").and_then(Value::as_u64) == Some(2)
                    && beam
                        .get("final_cumulative_meterset_weight")
                        .and_then(Value::as_u64)
                        == Some(1)
            })
        });
    if !complete {
        return Err(ReportError::MetadataShape {
            path: manifest_path.to_path_buf(),
            message: "expected_rt_plan must define the complete linked Plan report contract",
        });
    }
    Ok(fields)
}

