    fn coverage_row<'a>(report: &'a Value, case_id: &str) -> &'a Value {
        report
            .get("coverage_matrix")
            .and_then(Value::as_array)
            .and_then(|rows| {
                rows.iter()
                    .find(|row| row.get("case_id").and_then(Value::as_str) == Some(case_id))
            })
            .expect("coverage row should be present")
    }
